function process(data) {
  const text = data && data.selection;
  if (typeof text !== 'string') {
    throw new TypeError('selection must be a string');
  }

  return text
    .split(/(\r\n|\n|\r)/)
    .map((part, index) => {
      if (index % 2 !== 0 || part.trim() === '') {
        return part;
      }
      return part.startsWith('\t') ? part.slice(1) : part.replace(/^ {1,4}/, '');
    })
    .join('');
}
